  "inlineSchema": "// AI LifeHub — Prisma Database Schema\n// Database Engine: PostgreSQL\n\ngenerator client {\n  provider = \"prisma-client-js\"\n}\n\ndatasource db {\n  provider = \"postgresql\"\n  url      = env(\"DATABASE_URL\")\n}\n\n// ==========================================\n// ENUMS\n// ==========================================\n\nenum Role {\n  USER\n  ADMIN\n  PREMIUM\n}\n\nenum TaskStatus {\n  TODO\n  IN_PROGRESS\n  COMPLETED\n  ARCHIVED\n}\n\nenum TaskPriority {\n  LOW\n  MEDIUM\n  HIGH\n  URGENT\n}\n\nenum HabitFrequency {\n  DAILY\n  WEEKLY\n  MONTHLY\n}\n\nenum MoodType {\n  GREAT\n  GOOD\n  NEUTRAL\n  BAD\n  TERRIBLE\n}\n\nenum SenderType {\n  USER\n  ASSISTANT\n  SYSTEM\n}\n\n// ==========================================\n// USER & AUTHENTICATION MODELS\n// ==========================================\n\nmodel User {\n  id           String   @id @default(uuid())\n  email        String   @unique\n  passwordHash String\n  name         String?\n  role         Role     @default(USER)\n  avatarUrl    String?\n  isVerified   Boolean  @default(false)\n  createdAt    DateTime @default(now())\n  updatedAt    DateTime @updatedAt\n\n  // Relationships\n  profile       Profile?\n  sessions      Session[]\n  refreshTokens RefreshToken[]\n  tasks         Task[]\n  habits        Habit[]\n  journals      JournalEntry[]\n  moodLogs      MoodLog[]\n  conversations Conversation[]\n  aiInsights    AIInsight[]\n  usage         UserUsage?\n\n  @@index([email])\n}\n\nmodel Profile {\n  id               String   @id @default(uuid())\n  userId           String   @unique\n  user             User     @relation(fields: [userId], references: [id], onDelete: Cascade)\n  bio              String?\n  timezone         String   @default(\"UTC\")\n  themePreference  String   @default(\"dark\")\n  aiTonePreference String   @default(\"encouraging\")\n  updatedAt        DateTime @updatedAt\n}\n\nmodel Session {\n  id        String   @id @default(uuid())\n  userId    String\n  user      User     @relation(fields: [userId], references: [id], onDelete: Cascade)\n  token     String   @unique\n  ipAddress String?\n  userAgent String?\n  expiresAt DateTime\n  createdAt DateTime @default(now())\n\n  @@index([userId])\n}\n\nmodel RefreshToken {\n  id        String   @id @default(uuid())\n  userId    String\n  user      User     @relation(fields: [userId], references: [id], onDelete: Cascade)\n  token     String   @unique\n  revoked   Boolean  @default(false)\n  expiresAt DateTime\n  createdAt DateTime @default(now())\n\n  @@index([token])\n}\n\n// ==========================================\n// TASK & HABIT MANAGEMENT MODELS\n// ==========================================\n\nmodel Task {\n  id          String       @id @default(uuid())\n  userId      String\n  user        User         @relation(fields: [userId], references: [id], onDelete: Cascade)\n  title       String\n  description String?\n  status      TaskStatus   @default(TODO)\n  priority    TaskPriority @default(MEDIUM)\n  dueDate     DateTime?\n  aiSuggested Boolean      @default(false)\n  createdAt   DateTime     @default(now())\n  updatedAt   DateTime     @updatedAt\n\n  @@index([userId, status])\n}\n\nmodel Habit {\n  id          String         @id @default(uuid())\n  userId      String\n  user        User           @relation(fields: [userId], references: [id], onDelete: Cascade)\n  title       String\n  description String?\n  frequency   HabitFrequency @default(DAILY)\n  targetCount Int            @default(1)\n  logs        HabitLog[]\n  createdAt   DateTime       @default(now())\n  updatedAt   DateTime       @updatedAt\n\n  @@index([userId])\n}\n\nmodel HabitLog {\n  id        String   @id @default(uuid())\n  habitId   String\n  habit     Habit    @relation(fields: [habitId], references: [id], onDelete: Cascade)\n  completed Boolean  @default(true)\n  loggedAt  DateTime @default(now())\n\n  @@index([habitId, loggedAt])\n}\n\n// ==========================================\n// JOURNALING & MOOD TRACKING\n// ==========================================\n\nmodel JournalEntry {\n  id        String   @id @default(uuid())\n  userId    String\n  user      User     @relation(fields: [userId], references: [id], onDelete: Cascade)\n  title     String\n  content   String\n  sentiment String? // AI-analyzed sentiment (e.g., Positive, Neutral, Negative)\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@index([userId])\n}\n\nmodel MoodLog {\n  id       String   @id @default(uuid())\n  userId   String\n  user     User     @relation(fields: [userId], references: [id], onDelete: Cascade)\n  mood     MoodType\n  note     String?\n  loggedAt DateTime @default(now())\n\n  @@index([userId, loggedAt])\n}\n\n// ==========================================\n// AI CHAT & INSIGHTS\n// ==========================================\n\nmodel Conversation {\n  id        String    @id @default(uuid())\n  userId    String\n  user      User      @relation(fields: [userId], references: [id], onDelete: Cascade)\n  title     String    @default(\"New Conversation\")\n  messages  Message[]\n  createdAt DateTime  @default(now())\n  updatedAt DateTime  @updatedAt\n\n  @@index([userId])\n}\n\nmodel Message {\n  id             String       @id @default(uuid())\n  conversationId String\n  conversation   Conversation @relation(fields: [conversationId], references: [id], onDelete: Cascade)\n  sender         SenderType\n  content        String\n  tokensUsed     Int          @default(0)\n  createdAt      DateTime     @default(now())\n\n  @@index([conversationId])\n}\n\nmodel AIInsight {\n  id          String   @id @default(uuid())\n  userId      String\n  user        User     @relation(fields: [userId], references: [id], onDelete: Cascade)\n  category    String // Productivity, Wellness, Routine, Focus\n  insightText String\n  actionable  Boolean  @default(true)\n  createdAt   DateTime @default(now())\n\n  @@index([userId])\n}\n\n// ==========================================\n// SYSTEM & USAGE METRICS\n// ==========================================\n\nmodel UserUsage {\n  id              String   @id @default(uuid())\n  userId          String   @unique\n  user            User     @relation(fields: [userId], references: [id], onDelete: Cascade)\n  totalTokens     Int      @default(0)\n  monthlyRequests Int      @default(0)\n  lastResetDate   DateTime @default(now())\n  updatedAt       DateTime @updatedAt\n}\n",
